begin;
select plan(11);
insert into auth.users(instance_id,id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values ('00000000-0000-0000-0000-000000000000','aaaaaaaa-2222-2222-2222-222222222222','authenticated','authenticated','stats.a@example.com',now(),'{"provider":"email","providers":["email"]}','{}',now(),now()),('00000000-0000-0000-0000-000000000000','bbbbbbbb-2222-2222-2222-222222222222','authenticated','authenticated','stats.b@example.com',now(),'{"provider":"email","providers":["email"]}','{}',now(),now());
update public.profiles set timezone='Asia/Ho_Chi_Minh' where id='aaaaaaaa-2222-2222-2222-222222222222';
insert into public.quiz_sessions(id,user_id,mode,requested_question_count,actual_question_count,correct_answer_count,completed_at,started_at) values ('11111111-2222-2222-2222-222222222222','aaaaaaaa-2222-2222-2222-222222222222','balanced',10,10,8,now(),now()),('22222222-2222-2222-2222-222222222222','aaaaaaaa-2222-2222-2222-222222222222','pure_random',10,10,7,now()-interval '1 hour',now()-interval '1 hour'),('33333333-2222-2222-2222-222222222222','aaaaaaaa-2222-2222-2222-222222222222','balanced',10,10,0,null,now()),('44444444-2222-2222-2222-222222222222','bbbbbbbb-2222-2222-2222-222222222222','balanced',10,10,10,now(),now());
insert into public.daily_learning_records(user_id,local_date,timezone,completed_quiz_count,questions_answered,correct_answers,first_completed_at,last_completed_at) values ('aaaaaaaa-2222-2222-2222-222222222222',(now() at time zone 'Asia/Ho_Chi_Minh')::date,'Asia/Ho_Chi_Minh',2,20,15,now()-interval '1 hour',now());
set local role authenticated; set local request.jwt.claim.sub='aaaaaaaa-2222-2222-2222-222222222222';
select is((public.get_learning_statistics()->>'total_completed_quizzes')::int,2,'only completed quizzes are counted');
select is((public.get_learning_statistics()->>'questions_answered')::int,20,'question totals aggregate sessions');
select is((public.get_learning_statistics()->>'correct_answers')::int,15,'correct totals aggregate sessions');
select is((public.get_learning_statistics()->>'active_days')::int,1,'same-day sessions deduplicate activity');
select ok((public.get_learning_statistics()->>'completed_today')::boolean,'today is active');
select is((public.get_learning_statistics()->>'current_streak')::int,1,'current streak is one day');
select is((public.get_learning_statistics()->'mode_breakdown'->0->>'quiz_count')::int,1,'mode breakdown is aggregated');
set local request.jwt.claim.sub='bbbbbbbb-2222-2222-2222-222222222222';
select is((public.get_learning_statistics()->>'total_completed_quizzes')::int,1,'cross-user statistics are isolated');
reset role; set local role anon;
select throws_ok($$select public.get_learning_statistics()$$,'42501','permission denied for function get_learning_statistics','anonymous access is denied');
reset role;
update public.profiles set timezone='invalid/timezone' where id='aaaaaaaa-2222-2222-2222-222222222222'; set local role authenticated; set local request.jwt.claim.sub='aaaaaaaa-2222-2222-2222-222222222222';
select is(public.get_learning_statistics()->>'timezone','Asia/Ho_Chi_Minh','invalid timezone safely falls back');
select is((public.get_learning_statistics()->>'longest_streak')::int,1,'longest streak is derived');
select * from finish(); rollback;
